/**
 * End-to-end SPARQL tests for the RDF4J extension function namespaces (scalar functions and magic-property tuple
 * functions) evaluated on a {@link MemoryStore}.
 */
public class ExtensionFunctionSparqlTest {

	private static final String PREFIXES = "PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n"
			+ "PREFIX mathf: <http://rdf4j.org/function/math#>\n"
			+ "PREFIX strf: <http://rdf4j.org/function/string#>\n"
			+ "PREFIX dtf: <http://rdf4j.org/function/datetime#>\n"
			+ "PREFIX textf: <http://rdf4j.org/function/text#>\n"
			+ "PREFIX jsonf: <http://rdf4j.org/function/json#>\n"
			+ "PREFIX arrf: <http://rdf4j.org/function/array#>\n"
			+ "PREFIX bitf: <http://rdf4j.org/function/bitwise#>\n"
			+ "PREFIX encf: <http://rdf4j.org/function/encoding#>\n"
			+ "PREFIX miscf: <http://rdf4j.org/function/misc#>\n"
			+ "PREFIX ex: <http://example.org/>\n";

	private static SailRepository repository;

	@BeforeAll
	static void setUp() throws Exception {
		repository = new SailRepository(new MemoryStore());
		String data = "@prefix ex: <http://example.org/> .\n"
				+ "ex:a ex:name \"Alice Smith\" ; ex:tags \"red,green,blue\" ; ex:score 3 ; "
				+ "ex:doc \"{\\\"k\\\":[1,2,3],\\\"name\\\":\\\"n1\\\"}\"^^<http://www.w3.org/1999/02/22-rdf-syntax-ns#JSON> .\n"
				+ "ex:b ex:name \"Bob Jones\" ; ex:tags \"blue\" ; ex:score 5 ; "
				+ "ex:doc \"{\\\"k\\\":[4],\\\"name\\\":\\\"n2\\\"}\"^^<http://www.w3.org/1999/02/22-rdf-syntax-ns#JSON> .\n";
		try (RepositoryConnection conn = repository.getConnection()) {
			conn.add(new StringReader(data), "", RDFFormat.TURTLE);
		}
	}

	@AfterAll
	static void tearDown() {
		repository.shutDown();
	}

	private static List<BindingSet> query(String query) {
		try (RepositoryConnection conn = repository.getConnection();
				TupleQueryResult result = conn.prepareTupleQuery(PREFIXES + query).evaluate()) {
			return new ArrayList<>(QueryResults.asList(result));
		}
	}

	private static Value single(String query, String var) {
		List<BindingSet> rows = query(query);
		assertThat(rows).hasSize(1);
		return rows.get(0).getValue(var);
	}

	@Test
	void scalarFunctionsFromEveryNamespaceAreResolved() {
		assertThat(single("SELECT (mathf:sqrt(16) AS ?r) WHERE {}", "r").stringValue()).isEqualTo("4.0");
		assertThat(single("SELECT (mathf:greatest(1, 7.5, 3) AS ?r) WHERE {}", "r").stringValue()).isEqualTo("7.5");
		assertThat(single("SELECT (strf:lpad(\"7\", 3, \"0\") AS ?r) WHERE {}", "r").stringValue()).isEqualTo("007");
		assertThat(single("SELECT (strf:initCap(\"hello world\"@en) AS ?r) WHERE {}", "r"))
				.isEqualTo(repository.getValueFactory().createLiteral("Hello World", "en"));
		assertThat(single("SELECT (dtf:dateTrunc(\"month\", \"2024-05-17T10:11:12Z\"^^xsd:dateTime) AS ?r) WHERE {}",
				"r").stringValue()).isEqualTo("2024-05-01T00:00:00Z");
		assertThat(single("SELECT (dtf:dayOfWeek(\"2024-05-17\"^^xsd:date) AS ?r) WHERE {}", "r").stringValue())
				.isEqualTo("5");
		assertThat(single("SELECT (textf:levenshtein(\"kitten\", \"sitting\") AS ?r) WHERE {}", "r").stringValue())
				.isEqualTo("3");
		assertThat(single("SELECT (textf:ilike(\"Hello\", \"h%\") AS ?r) WHERE {}", "r").stringValue())
				.isEqualTo("true");
		assertThat(single("SELECT (jsonf:jsonValue('{\"a\":{\"b\":42}}', \"$.a.b\") AS ?r) WHERE {}", "r"))
				.isEqualTo(repository.getValueFactory().createLiteral(java.math.BigInteger.valueOf(42)));
		assertThat(single("SELECT (arrf:arrayContains(strf:split(\"a,b\", \",\"), \"b\") AS ?r) WHERE {}", "r")
				.stringValue()).isEqualTo("true");
		assertThat(single("SELECT (bitf:bitXor(12, 10) AS ?r) WHERE {}", "r").stringValue()).isEqualTo("6");
		assertThat(single("SELECT (encf:base64Encode(\"hello\") AS ?r) WHERE {}", "r").stringValue())
				.isEqualTo("aGVsbG8=");
		assertThat(single("SELECT (encf:crc32(\"hello\") AS ?r) WHERE {}", "r").stringValue())
				.isEqualTo("907060870");
	}

	@Test
	void nullIfLeavesVariableUnboundOnEquality() {
		List<BindingSet> rows = query("SELECT ?s ?r WHERE { ?s ex:score ?score . BIND(miscf:nullIf(?score, 5) AS ?r) }"
				+ " ORDER BY ?s");
		assertThat(rows).hasSize(2);
		assertThat(rows.get(0).getValue("r").stringValue()).isEqualTo("3");
		assertThat(rows.get(1).hasBinding("r")).isFalse();
	}

	@Test
	void functionsInFilterAndWithDataBoundArguments() {
		List<BindingSet> rows = query("SELECT ?s WHERE { ?s ex:name ?n . FILTER(strf:position(\"Smith\", ?n) > 0) }");
		assertThat(rows).hasSize(1);
		assertThat(rows.get(0).getValue("s").stringValue()).isEqualTo("http://example.org/a");
		rows = query("SELECT ?s (jsonf:jsonArrayLength(?doc, \"$.k\") AS ?n) WHERE { ?s ex:doc ?doc } ORDER BY ?s");
		assertThat(rows).extracting(bs -> bs.getValue("n").stringValue()).containsExactly("3", "1");
	}

	@Test
	void magicPropertySplitWithCollectionArguments() {
		List<BindingSet> rows = query(
				"SELECT ?s ?tag WHERE { ?s ex:tags ?tags . (?tags \",\") strf:split (?tag) } ORDER BY ?s ?tag");
		assertThat(rows).extracting(bs -> bs.getValue("tag").stringValue())
				.containsExactly("blue", "green", "red", "blue");
		assertThat(rows.get(3).getValue("s").stringValue()).isEqualTo("http://example.org/b");
	}

	@Test
	void magicPropertyWithConstantsOnlyAndSingleTermForms() {
		List<BindingSet> rows = query("SELECT ?n WHERE { (1 5 2) arrf:generateSeries (?n) }");
		assertThat(rows).extracting(bs -> bs.getValue("n").stringValue()).containsExactly("1", "3", "5");
		rows = query("SELECT ?token WHERE { \"to be, or not\" textf:tokenize ?token }");
		assertThat(rows).extracting(bs -> bs.getValue("token").stringValue())
				.containsExactly("to", "be", "or", "not");
		rows = query("SELECT ?g WHERE { (\"abc\" 2) textf:ngrams (?g) }");
		assertThat(rows).extracting(bs -> bs.getValue("g").stringValue()).containsExactly("ab", "bc");
	}

	@Test
	void magicPropertyUnnestFromData() {
		List<BindingSet> rows = query(
				"SELECT ?s ?v WHERE { ?s ex:doc ?doc . BIND(jsonf:jsonQuery(?doc, \"$.k\") AS ?arr)"
						+ " ?arr arrf:unnest ?v } ORDER BY ?s ?v");
		assertThat(rows).extracting(bs -> bs.getValue("v").stringValue()).containsExactly("1", "2", "3", "4");
		assertThat(rows.get(0).getValue("v")).isInstanceOf(Literal.class);
		assertThat(((Literal) rows.get(0).getValue("v")).getDatatype()).isEqualTo(XSD.INTEGER);
		rows = query("SELECT ?s ?v ?i WHERE { ?s ex:doc ?doc . BIND(jsonf:jsonQuery(?doc, \"$.k\") AS ?arr)"
				+ " ?arr arrf:unnestWithOrdinality (?v ?i) FILTER(?i = 1) } ORDER BY ?s");
		assertThat(rows).extracting(bs -> bs.getValue("v").stringValue()).containsExactly("1", "4");
	}

	@Test
	void magicPropertyResultCanBeConstrainedByBoundValue() {
		List<BindingSet> rows = query(
				"SELECT ?s WHERE { ?s ex:tags ?tags . (?tags \",\") strf:split (\"green\") }");
		assertThat(rows).hasSize(1);
		assertThat(rows.get(0).getValue("s").stringValue()).isEqualTo("http://example.org/a");
		rows = query("SELECT ?s WHERE { ?s ex:tags ?tags . VALUES ?tag { \"blue\" } (?tags \",\") strf:split (?tag) }"
				+ " ORDER BY ?s");
		assertThat(rows).extracting(bs -> bs.getValue("s").stringValue())
				.containsExactly("http://example.org/a", "http://example.org/b");
	}

	@Test
	void magicPropertyInsideNestedGroupAndOptional() {
		List<BindingSet> rows = query("SELECT ?s ?tag WHERE { ?s ex:name ?n . OPTIONAL { ?s ex:tags ?tags ."
				+ " (?tags \",\") strf:split (?tag) FILTER(?tag != \"blue\") } } ORDER BY ?s ?tag");
		assertThat(rows).hasSize(3);
		assertThat(rows.get(2).getValue("s").stringValue()).isEqualTo("http://example.org/b");
		assertThat(rows.get(2).hasBinding("tag")).isFalse();
	}

	@Test
	void unknownPredicatesAreUntouched() {
		List<BindingSet> rows = query("SELECT ?s WHERE { (?s \",\") ex:notAFunction (?x) }");
		assertThat(rows).isEmpty();
	}

	@Test
	void regexpExtractAllScalarReturnsJsonArray() {
		Value v = single("SELECT (strf:regexpExtractAll(\"a1b22\", \"[0-9]+\") AS ?r) WHERE {}", "r");
		assertThat(((Literal) v).getCoreDatatype()).isEqualTo(CoreDatatype.RDF.JSON);
		assertThat(v.stringValue()).isEqualTo("[\"1\",\"22\"]");
	}
}
